// nOf(preset) = quantos pedaços o texto tem na divisão daquele preset.
export function layerPhase(anim, nOf, lt, len, seed) {
  if (!anim) return null;
  const pin = presetByName(anim.in), pout = presetByName(anim.out), pem = presetByName(anim.emph);
  const Pin = pin && makePlan(pin, nOf(pin), seed), Pout = pout && makePlan(pout, nOf(pout), seed + 1), Pem = pem && makePlan(pem, nOf(pem), seed + 2);
  const outStart = Pout ? Math.max(Pin ? Pin.dur / 1000 : 0, len - Pout.dur / 1000) : Infinity;
  if (Pout && lt >= outStart) return { P: Pout, t: (lt - outStart) * 1000 };
  if (Pin && lt * 1000 < Pin.dur) return { P: Pin, t: lt * 1000 };
  if (Pem) return { P: Pem, t: emphasisTime(Pem, (lt - (Pin ? Pin.dur / 1000 : 0)) * 1000) };
  return null;
}
export const hasAnim = (a) => !!(a && (a.in || a.out || a.emph));
// Divide linhas de texto em pedaços (letra, palavra ou linha) com a caixa de cada um.
// lines: [{ text, x, y, w }] já posicionadas (x = esquerda, y = centro). Devolve [{ s, x, y, w, h }].
export function splitSlices(ctx, lines, mode, lh) {
  const out = [];
  for (const ln of lines) {
    if (mode === 'l') { out.push({ s: ln.text, x: ln.x, y: ln.y, w: ln.w, h: lh }); continue; }
    if (mode === 'w') {
      let x = ln.x; const sp = ctx.measureText(' ').width;
      for (const w of ln.text.split(' ')) { if (!w) { x += sp; continue; } const ww = ctx.measureText(w).width; out.push({ s: w, x, y: ln.y, w: ww, h: lh }); x += ww + sp; }
      continue;
    }
    const chars = typeof Intl !== 'undefined' && Intl.Segmenter ? [...new Intl.Segmenter('pt-BR', { granularity: 'grapheme' }).segment(ln.text)].map((g) => g.segment) : [...ln.text];
    let acc = '';
    for (const c of chars) { const x = ln.x + ctx.measureText(acc).width; acc += c; const w = ctx.measureText(c).width; if (c.trim()) out.push({ s: c, x, y: ln.y, w, h: lh }); }
  }
  return out;
}
